import { createHash } from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { voiceDir } from './config';

/**
 * Scripted lines: never generated by a model. Each is rendered once to audio with the agent's own voice, stored
 * with a SHA-256 of its PCM (checked on every load) and played byte for byte by the orchestrator. The model asks
 * for one with the say_script tool; the orchestrator also plays some on its own (greeting, emergency backstop,
 * transfer, hold, staff unavailable). The exact text is added to the model's conversation as the assistant turn.
 */
export const MODEL_SCRIPTS = ['EMERGENCY_911', 'NO_MEDICAL_ADVICE', 'RECORDS_DOWN', 'CANT_VERIFY', 'GOODBYE'] as const;
export type ScriptId =
  | (typeof MODEL_SCRIPTS)[number]
  | 'GREETING'
  | 'GREETING_AFTER_HOURS'
  | 'TRANSFER'
  | 'HOLD'
  | 'STAFF_UNAVAILABLE'
  | 'TRANSFER_FAILED'
  | 'TRANSFER_VOICEMAIL'
  | 'PARK';

/** Lines that must be ready before a call is accepted (fail closed: the PBX's no-answer route takes the call). */
export const REQUIRED_SCRIPTS: ScriptId[] = ['GREETING', 'GREETING_AFTER_HOURS', 'EMERGENCY_911', 'NO_MEDICAL_ADVICE', 'TRANSFER', 'RECORDS_DOWN'];

export function scriptTexts(clinicName: string): Record<ScriptId, string> {
  const clinic = clinicName.trim() || 'our clinic';
  return {
    GREETING: `Thank you for calling ${clinic}. This is the automated assistant. How can I help you today?`,
    GREETING_AFTER_HOURS: `Thank you for calling ${clinic}. Our office is closed right now, and this is the after-hours automated assistant. How can I help you?`,
    EMERGENCY_911: 'If this is an emergency, please hang up and call 911 now.',
    NO_MEDICAL_ADVICE: "I can't give medical advice, but I can connect you with our staff or send them a message.",
    RECORDS_DOWN: "I'm sorry, I can't reach our records system right now.",
    CANT_VERIFY: "I'm not able to verify that.",
    GOODBYE: 'Thank you for calling. Goodbye.',
    TRANSFER: 'Let me connect you with our staff now.',
    HOLD: 'Please stay on the line while I reach someone for you.',
    STAFF_UNAVAILABLE: "I'm sorry, I couldn't reach anyone just now. I can send you to voicemail, or take a message for our staff.",
    TRANSFER_FAILED: "I'm sorry, I can't connect you to staff on this line right now. I can take a message instead.",
    TRANSFER_VOICEMAIL: "I'll send you to voicemail now. Please leave your message after the tone.",
    PARK: 'Please hold. A member of our staff will pick up your call shortly.',
  };
}

export interface Clip {
  id: string;
  text: string;
  pcm: Buffer;
  rate: number;
  sha256: string;
}

/** Text to speech for one clip: PCM s16le mono at `rate`. Throws on failure. */
export type TtsRenderer = (text: string, voice: string, rate: number) => Promise<Buffer>;

const sha = (b: Buffer | string) => createHash('sha256').update(b).digest('hex');

export class ClipStore {
  private clips = new Map<string, Clip>();
  constructor(private readonly dir = path.join(voiceDir(), 'clips')) {}

  private key(provider: string, voice: string, rate: number, text: string) {
    return sha(`${provider}|${voice}|${rate}|${text}`);
  }

  get(provider: string, voice: string, rate: number, text: string): Clip | undefined {
    return this.clips.get(this.key(provider, voice, rate, text));
  }

  /** Load from disk (hash-checked) or render, for every script. Returns the IDs that are not available. */
  async ensure(provider: string, voice: string, rate: number, texts: Record<string, string>, render: TtsRenderer): Promise<string[]> {
    const missing: string[] = [];
    fs.mkdirSync(this.dir, { recursive: true, mode: 0o700 });
    for (const [id, text] of Object.entries(texts)) {
      const k = this.key(provider, voice, rate, text);
      if (this.clips.has(k)) continue;
      const file = path.join(this.dir, `${k}.pcm`);
      const sumFile = `${file}.sha256`;
      try {
        const pcm = fs.readFileSync(file);
        const want = fs.readFileSync(sumFile, 'utf8').trim();
        if (sha(pcm) === want && pcm.length > rate / 5) {
          this.clips.set(k, { id, text, pcm, rate, sha256: want });
          continue;
        }
        console.warn(`[Voice] clip ${id} failed its checksum; rendering again`);
      } catch {
        // not cached yet
      }
      try {
        const pcm = await render(text, voice, rate);
        if (pcm.length < rate / 5) throw new Error('clip too short');
        const sum = sha(pcm);
        fs.writeFileSync(file, pcm, { mode: 0o600 });
        fs.writeFileSync(sumFile, sum, { mode: 0o600 });
        this.clips.set(k, { id, text, pcm, rate, sha256: sum });
      } catch (e: any) {
        console.error(`[Voice] clip ${id} could not be rendered (${String(e?.message || 'error').slice(0, 80)})`);
        missing.push(id);
      }
    }
    return missing;
  }

  /** Test hook: put a clip in directly. */
  put(provider: string, voice: string, rate: number, id: string, text: string, pcm: Buffer): void {
    this.clips.set(this.key(provider, voice, rate, text), { id, text, pcm, rate, sha256: sha(pcm) });
  }
}

// ── TTS renderers ────────────────────────────────────────────────────────────────────────────────────────────

/** OpenAI /v1/audio/speech, PCM 24 kHz. The clip text never contains patient data. */
export function openAiTts(apiKey: string, model = process.env.VOICE_TTS_MODEL || 'gpt-4o-mini-tts'): TtsRenderer {
  return async (text, voice, rate) => {
    if (rate !== 24000) throw new Error('OpenAI speech is 24 kHz');
    const r = await fetch('https://api.openai.com/v1/audio/speech', {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model, voice, input: text, response_format: 'pcm', instructions: 'Warm, calm, clear front-desk voice. Moderate pace.' }),
      signal: AbortSignal.timeout(20_000),
    });
    if (!r.ok) throw new Error(`speech http ${r.status}`);
    return Buffer.from(await r.arrayBuffer());
  };
}

/** ElevenLabs text to speech in the agent's voice, PCM at 16 or 24 kHz. */
export function elevenLabsTts(apiKey: string, model = process.env.VOICE_ELEVENLABS_TTS_MODEL || 'eleven_flash_v2_5'): TtsRenderer {
  return async (text, voice, rate) => {
    if (rate !== 16000 && rate !== 24000) throw new Error('unsupported rate');
    if (!/^[A-Za-z0-9]{8,40}$/.test(voice)) throw new Error('voice id format');
    const r = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voice}?output_format=pcm_${rate}`, {
      method: 'POST',
      headers: { 'xi-api-key': apiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ text, model_id: model }),
      signal: AbortSignal.timeout(20_000),
    });
    if (!r.ok) throw new Error(`tts http ${r.status}`);
    return Buffer.from(await r.arrayBuffer());
  };
}
